package com.cpf.notification.email;import com.cpf.notification.spi.CpfNotificationProvider;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.Bean;import org.springframework.core.env.Environment;import org.springframework.mail.javamail.JavaMailSender;
@AutoConfiguration @ConditionalOnProperty(prefix="cpf.notification.email",name="enabled",havingValue="true") public class CpfEmailNotificationAutoConfiguration {@Bean CpfNotificationProvider cpfEmailNotificationProvider(JavaMailSender sender,Environment env){String from=env.getRequiredProperty("cpf.notification.email.from");return new CpfEmailNotificationProvider(sender,from);}}
